var depthSum = function(nestedList) {
    function dfs(list, depth) {
        let total = 0;
        for (const item of list) {
            if (item.isInteger()) {
                total += item.getInteger() * depth;
            } else {
                total += dfs(item.getList(), depth + 1);
            }
        }
        return total;
    }
    return dfs(nestedList, 1);
};
